import React, { useState } from "react";
import toast from "react-hot-toast";
import { FiCheck, FiX, FiEye, FiDownload, FiFileText, FiSend } from "react-icons/fi";

const PrescriptionTab = () => {
  const [requests, setRequests] = useState([
    {
      id: "REQ-2094",
      buyer: "Surbhi Gupta",
      product: "Amoxicillin 500mg",
      fileName: "rx-surbhi-gupta-amox.pdf",
      date: "2026-06-14",
      status: "Pending Verification",
    },
    {
      id: "REQ-2081",
      buyer: "Rahul Sharma",
      product: "Metformin 500mg",
      fileName: "rx-rahul-metformin.jpg",
      date: "2026-06-12",
      status: "Approved",
    },
    {
      id: "REQ-2077",
      buyer: "Rohan Joshi",
      product: "Tramadol 50mg",
      fileName: "rx-rohan-tramadol.pdf",
      date: "2026-06-10",
      status: "Rejected",
    },
  ]);

  const [activePreview, setActivePreview] = useState(null);
  const [showProposalModal, setShowProposalModal] = useState(false);
  const [proposalReq, setProposalReq] = useState(null);
  const [proposalForm, setProposalForm] = useState({
    price: "",
    discount: "0",
    delivery: "0",
    eta: "24 Hours",
    payment: "UPI / Cash on Delivery",
  });

  const handleOpenProposal = (req) => {
    setProposalReq(req);
    setProposalForm({
      price: req.product.includes("Amoxicillin") ? "150" : "180",
      discount: "5",
      delivery: "30",
      eta: "24 Hours",
      payment: "UPI / Cash on Delivery",
    });
    setShowProposalModal(true);
  };

  const submitProposal = (e) => {
    e.preventDefault();
    toast.success(`Proposal for ${proposalReq.id} submitted successfully!`);
    setShowProposalModal(false);
  };

  const handleApprove = (id) => {
    setRequests(
      requests.map((r) => (r.id === id ? { ...r, status: "Approved" } : r))
    );
    toast.success(`Prescription for ${id} approved.`);
  };

  const handleReject = (id) => {
    setRequests(
      requests.map((r) => (r.id === id ? { ...r, status: "Rejected" } : r))
    );
    toast.error(`Prescription for ${id} rejected.`);
  };

  return (
    <div className="prescription-tab animate-fade-in">
      <h3 style={{ fontSize: "22px", fontWeight: "800", color: "#0F172A", marginBottom: "20px" }}>
        Prescription Verification Desk
      </h3>

      <div className="dashboard-card p-4">
        <h4 style={{ fontSize: "16px", fontWeight: "700", color: "#0F172A", marginBottom: "20px" }}>
          Prescription Validation Queue
        </h4>

        <div className="table-responsive">
          <table className="table align-middle">
            <thead className="table-light">
              <tr style={{ fontSize: "12px", color: "#475569", fontWeight: "700" }}>
                <th>Request ID</th>
                <th>Buyer Name</th>
                <th>Product Name</th>
                <th>Uploaded File</th>
                <th>Upload Date</th>
                <th>Verification Status</th>
                <th className="text-center">Review Actions</th>
              </tr>
            </thead>
            <tbody>
              {requests.map((req) => (
                <tr key={req.id} style={{ fontSize: "13px", color: "#334155" }}>
                  <td className="fw-700 text-main">{req.id}</td>
                  <td className="fw-600">{req.buyer}</td>
                  <td className="fw-700">{req.product}</td>
                  <td>
                    <span
                      onClick={() => setActivePreview(req)}
                      className="d-inline-flex align-items-center gap-1 text-primary cursor-pointer fw-600 hover-underline"
                    >
                      <FiFileText size={14} /> {req.fileName}
                    </span>
                  </td>
                  <td>{req.date}</td>
                  <td>
                    <span
                      className={`badge rounded-pill ${
                        req.status === "Approved"
                          ? "bg-success-subtle text-success"
                          : req.status === "Rejected"
                          ? "bg-danger-subtle text-danger"
                          : "bg-warning-subtle text-warning"
                      } px-2.5 py-1`}
                    >
                      {req.status}
                    </span>
                  </td>
                  <td>
                    <div className="d-flex gap-2 justify-content-center">
                      <button
                        onClick={() => setActivePreview(req)}
                        className="btn-action btn-view"
                        title="View Document"
                      >
                        <FiEye size={13} />
                      </button>
                      
                      {req.status === "Pending Verification" && (
                        <>
                          <button
                            onClick={() => handleApprove(req.id)}
                            className="btn-action btn-approve"
                            title="Approve prescription"
                          >
                            <FiCheck size={13} />
                          </button>
                          <button
                            onClick={() => handleReject(req.id)}
                            className="btn-action btn-reject"
                            title="Reject prescription"
                          >
                            <FiX size={13} />
                          </button>
                        </>
                      )}

                      {req.status === "Approved" && (
                        <button
                          onClick={() => handleOpenProposal(req)}
                          className="btn-action btn-approve"
                          title="Submit Proposal"
                        >
                          <FiSend size={13} />
                        </button>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* PRESCRIPTION PREVIEW MODAL */}
      {activePreview && (
        <div className="dashboard-modal-overlay">
          <div className="dashboard-modal-content" style={{ maxWidth: "480px" }}>
            <div className="d-flex justify-content-between align-items-center mb-4 pb-2 border-bottom">
              <h4 className="mb-0 text-heading fw-800">Review Document</h4>
              <button onClick={() => setActivePreview(null)} className="btn-close-modal">
                <FiX size={20} />
              </button>
            </div>

            <div className="text-center p-4 bg-light rounded-3 mb-4" style={{ border: "1px dashed #CBD5E1" }}>
              <FiFileText size={48} className="text-secondary mb-3" />
              <h5 className="mb-1 text-heading fw-800">{activePreview.fileName}</h5>
              <p className="text-muted small mb-3">Uploaded by {activePreview.buyer} on {activePreview.date}</p>
              
              <div className="p-3 bg-white border rounded text-start mb-3" style={{ fontSize: "12px", fontFamily: "monospace" }}>
                <strong>Prescription Details:</strong>
                <br />Patient: {activePreview.buyer}
                <br />Rx: {activePreview.product}
                <br />Clinic: Apollo Medical Center
                <br />Doctor: Dr. Ramesh K. (Reg No: MC-92842)
              </div>

              <button
                onClick={() => toast.success("Downloading document file...")}
                className="btn btn-outline-secondary btn-sm pill d-inline-flex align-items-center gap-1.5 px-3 py-1.5"
                style={{ fontSize: "12px" }}
              >
                <FiDownload size={13} /> Download File
              </button>
            </div>

            <div className="d-flex justify-content-end gap-2 pt-3 border-top">
              <button onClick={() => setActivePreview(null)} className="btn btn-light pill px-4">
                Close
              </button>
              {activePreview.status === "Pending Verification" && (
                <>
                  <button
                    onClick={() => {
                      handleReject(activePreview.id);
                      setActivePreview(null);
                    }}
                    className="btn btn-danger pill px-4"
                  >
                    Reject
                  </button>
                  <button
                    onClick={() => {
                      handleApprove(activePreview.id);
                      setActivePreview(null);
                    }}
                    className="btn btn-success pill px-4"
                  >
                    Approve
                  </button>
                </>
              )}
              {activePreview.status === "Approved" && (
                <button
                  onClick={() => {
                    handleOpenProposal(activePreview);
                    setActivePreview(null);
                  }}
                  className="btn btn-main pill px-4"
                  style={{ backgroundColor: "#A847F0", color: "white", border: "none" }}
                >
                  Submit Proposal
                </button>
              )}
            </div>
          </div>
        </div>
      )}

      {/* PROPOSAL SUBMIT MODAL */}
      {showProposalModal && proposalReq && (
        <div className="dashboard-modal-overlay">
          <div className="dashboard-modal-content">
            <div className="d-flex justify-content-between align-items-center mb-4 pb-2 border-bottom">
              <h4 className="mb-0 text-heading fw-800">Submit Proposal for {proposalReq.id}</h4>
              <button onClick={() => setShowProposalModal(false)} className="btn-close-modal">
                <FiX size={20} />
              </button>
            </div>
            
            <form onSubmit={submitProposal}>
              <div className="row gy-3">
                <div className="col-12">
                  <div className="p-3 bg-light rounded-3 mb-2">
                    <span className="text-muted small d-block">Requested Product</span>
                    <strong className="text-heading font-16">{proposalReq.product}</strong>
                  </div>
                </div>

                <div className="col-sm-6">
                  <label className="form-label fw-700 text-heading mb-1 small">Offered Unit Price (₹)</label>
                  <input
                    type="number"
                    required
                    className="common-input border"
                    value={proposalForm.price}
                    onChange={(e) => setProposalForm({ ...proposalForm, price: e.target.value })}
                  />
                </div>

                <div className="col-sm-6">
                  <label className="form-label fw-700 text-heading mb-1 small">Discount (%)</label>
                  <input
                    type="number"
                    className="common-input border"
                    value={proposalForm.discount}
                    onChange={(e) => setProposalForm({ ...proposalForm, discount: e.target.value })}
                  />
                </div>

                <div className="col-sm-6">
                  <label className="form-label fw-700 text-heading mb-1 small">Delivery Charge (₹)</label>
                  <input
                    type="number"
                    className="common-input border"
                    value={proposalForm.delivery}
                    onChange={(e) => setProposalForm({ ...proposalForm, delivery: e.target.value })}
                  />
                </div>

                <div className="col-sm-6">
                  <label className="form-label fw-700 text-heading mb-1 small">Delivery Duration</label>
                  <select
                    className="form-select border shadow-none"
                    style={{ height: "46px", borderRadius: "8px", fontSize: "14px" }}
                    value={proposalForm.eta}
                    onChange={(e) => setProposalForm({ ...proposalForm, eta: e.target.value })}
                  >
                    {Array.from({ length: 24 }, (_, i) => {
                      const hours = i + 1;
                      const label = hours === 1 ? "1 Hour" : `${hours} Hours`;
                      return (
                        <option key={hours} value={label}>
                          {label}
                        </option>
                      );
                    })}
                    <option value="48 Hours">48 Hours</option>
                    <option value="3-5 Days">3-5 Days</option>
                  </select>
                </div>

                <div className="col-12">
                  <label className="form-label fw-700 text-heading mb-1 small">Supported Payment Methods</label>
                  <input
                    type="text"
                    required
                    className="common-input border"
                    placeholder="e.g. UPI / Cash on Delivery / Cards"
                    value={proposalForm.payment}
                    onChange={(e) => setProposalForm({ ...proposalForm, payment: e.target.value })}
                  />
                </div>
              </div>

              <div className="d-flex justify-content-end gap-2 mt-4 pt-3 border-top">
                <button
                  type="button"
                  onClick={() => setShowProposalModal(false)}
                  className="btn btn-light pill px-4"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="btn btn-main pill px-4"
                  style={{ backgroundColor: "#A847F0", color: "white", border: "none" }}
                >
                  Send Proposal
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      <style>{`
        .btn-action {
          width: 32px;
          height: 32px;
          border-radius: 6px;
          border: none;
          display: inline-flex;
          align-items: center;
          justify-content: center;
          cursor: pointer;
          transition: all 0.2s;
        }
        .btn-view {
          background-color: #F1F5F9;
          color: #475569;
        }
        .btn-view:hover {
          background-color: #E2E8F0;
        }
        .btn-approve {
          background-color: #ECFDF5;
          color: #10B981;
        }
        .btn-approve:hover {
          background-color: #D1FAE5;
        }
        .btn-reject {
          background-color: #FEF2F2;
          color: #EF4444;
        }
        .btn-reject:hover {
          background-color: #FEE2E2;
        }
        .text-main {
          color: #A847F0 !important;
        }
        .bg-warning-subtle {
          background-color: #FEF3C7 !important;
        }
        .bg-primary-subtle {
          background-color: #E0E7FF !important;
        }
        .bg-success-subtle {
          background-color: #D1FAE5 !important;
        }
        .bg-danger-subtle {
          background-color: #FEE2E2 !important;
        }

        /* Modal styling */
        .dashboard-modal-overlay {
          position: fixed;
          top: 0;
          left: 0;
          right: 0;
          bottom: 0;
          background-color: rgba(15, 23, 42, 0.6);
          backdrop-filter: blur(4px);
          display: flex;
          align-items: center;
          justify-content: center;
          z-index: 9999;
          padding: 15px;
        }
        .dashboard-modal-content {
          background-color: #ffffff;
          border-radius: 16px;
          width: 100%;
          max-width: 520px;
          padding: 28px;
          box-shadow: 0 20px 25px -5px rgba(0,0,0,0.1), 0 10px 10px -5px rgba(0,0,0,0.04);
        }
        .btn-close-modal {
          border: none;
          background: none;
          color: #64748B;
          cursor: pointer;
          display: flex;
          align-items: center;
          justify-content: center;
          padding: 4px;
          border-radius: 50%;
          transition: all 0.2s;
        }
        .btn-close-modal:hover {
          background-color: #F1F5F9;
          color: #0F172A;
        }
      `}</style>

    </div>
  );
};

export default PrescriptionTab;
